//! Safe, reusable `PipeWire` native-protocol and `ClientNode` primitives.
//!
//! Portal streams use the native protocol directly over the portal-provided FD.
//! SPA POD encoding and decoding is provided by `pipewire-native-spa`; this
//! crate does not link to libpipewire or require `PipeWire` development headers.

pub use pipewire_native_spa as spa;

pub mod audio;
pub mod client;
pub mod format;
pub mod node;
pub mod remote;
pub mod stream;
pub mod transport;

/// Compile-time protocol and target information generated by the crate build script.
pub mod build_info {
    include!(concat!(env!("OUT_DIR"), "/build_info.rs"));
}

pub use audio::{AudioControls, AudioFormatCaps, AudioSampleFormat, NegotiatedAudioFormat};
pub use client::{PipeWireGlobal, PipeWireObject, PipeWireParam};
pub use node::{ClientNode, ClientNodeEvent, IoBuffers, PipeWireBuffer, PortDirection};
pub use remote::PipeWireRemote;
pub use stream::{
    AudioFrame, AudioStream, PipeWireStream, PipeWireStreamState, Stream, StreamOptions, VideoFrame,
};
